<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { canPublishReview, isWriting, criteriaFor, reviewComplete, type ExamItem } from '../assessment'
import {canResolveGrade,modelSucceeded,runLabel,type ProviderStatus,type AIRun} from '../aiAssessment'
import type {TallyAttempt} from '../tally'
const props=defineProps<{request:(path:string,method?:string,body?:unknown)=>Promise<any>}>()
const emit=defineEmits<{close:[]}>()
interface Student {user_id:string;name:string;class_id:string;demo:boolean;route_count:number;attempt_count:number;published_total:number|null}
interface TeacherAttempt {id:string;exam_id:string;status:string;total:number|null;max_score:number;answers:Record<string,unknown>;item_scores:Record<string,number|null>;created_at:string;published_at:string|null;items?:ExamItem[];review_comment?:string;ai_grade?:AIRun|null;review_history?:{id:string;teacher_id:string;scores:Record<string,number>;criteria?:Record<string,number[]>|null;comment:string;created_at:string}[]}
interface Evidence {kind:string;text:string;route_id:string;artifact_id?:string;support_count:number;node_id?:string;author_name?:string;support_ids?:string[]}
interface S11Record {id?:string;route_id:string;node_id:string;author_name?:string;account_id?:string|null;text?:string;kind?:string;level?:string;source?:string;created_at?:string;support_ids?:string[];action?:unknown;label?:string;reaction?:unknown}
interface ProcessPoint {sequence:number;side:string;feedback_before?:string[];support_ids?:string[]}
interface ProcessTask {id:string;record_id:string;route_id:string;node_id:string;task_id:string;actor_id:string;author_name:string;account_id:string|null;activity_mode:string;created_at:string;revision:number;feedback_display?:{id:string;text:string;sequence:number}[];payload:{status:string;placements?:unknown[];blocked_after?:boolean;walked?:boolean;first_attempt?:ProcessPoint|null;attempts?:ProcessPoint[];feedback?:unknown[];selected_side?:string;heard?:{clip_id:string;mode:string;sequence:number}[];replays?:Record<string,number>;response?:string}}
interface Detail {student:Student;routes:{id:string;role:string;status:string;created_at:string;parent_route_id?:string|null;version?:string}[];s11?:{expressions:S11Record[];supports:S11Record[];events:S11Record[];old_utterances?:S11Record[];tasks?:ProcessTask[]};matrix:{goal_id:string;title:string;status:string;description:string;evidence:Evidence[]}[];attempts:TeacherAttempt[];comment:{text:string;version:number;updated_at:string;teacher_id:string;status?:string}|null;published_comment?:{text:string;version:number;updated_at:string}|null;ai_mode:string;limitations:string[]}
interface Detail {ai_assessment?:{provider:ProviderStatus;latest_analysis:AIRun|null}}
const students=ref<Student[]>([]),detail=ref<Detail|null>(null),items=ref<ExamItem[]>([]),selectedId=ref(''),search=ref(''),selectedAttempt=ref('')
const loading=ref(true),detailLoading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),comment=ref(''),reviewComment=ref('')
const scores=ref<Record<string,number|null>>({})
const criteria=ref<Record<string,(number|null)[]>>({})
const aiState=ref<{provider:ProviderStatus;latest_analysis:AIRun|null}|null>(null),fallbackConfirmed=ref(false),objectiveResolution=ref<Record<string,number|null>>({})
const objectiveDirty=ref(false)
let selectionVersion=0
const filtered=computed(()=>students.value.filter(s=>`${s.name} ${s.user_id} ${s.class_id}`.toLowerCase().includes(search.value.toLowerCase())))
const attempt=computed(()=>detail.value?.attempts.find(a=>a.id===selectedAttempt.value))
const processTasks=computed(()=>{const latest=new Map<string,ProcessTask>();for(const task of detail.value?.s11?.tasks??[]){const key=`${task.route_id}:${task.record_id}`;const previous=latest.get(key);if(!previous||task.revision>=previous.revision)latest.set(key,task)}return [...latest.values()].sort((a,b)=>b.created_at.localeCompare(a.created_at))})
const taskNames:Record<string,string>={M03_PASSAGE:'给船上留通路',M07_SIDE:'指出朝岸的一舷',M09_LISTEN:'重听停射与岸上动静',M12_TALLY:'归岸核对箭数'}
function tallyAttempts(task:ProcessTask){return (task.payload.attempts??[]) as unknown as TallyAttempt[]}
function sideName(side?:string){return side==='left'?'左舷':side==='right'?'右舷':'尚未指出'}
const activeItems=computed(()=>attempt.value?.items??items.value)
const openItems=computed(()=>activeItems.value.filter(isWriting))
const objectiveItems=computed(()=>activeItems.value.filter(i=>!isWriting(i)))
const objectiveMax=computed(()=>objectiveItems.value.reduce((sum,q)=>sum+q.points,0))
const canReview=computed(()=>!!reviewComment.value.trim()&&reviewComplete(openItems.value,criteria.value)&&!!attempt.value&&canResolveGrade(attempt.value.exam_id,attempt.value.ai_grade,fallbackConfirmed.value,objectiveResolution.value))
const conflicts=computed(()=>attempt.value?.ai_grade?.result.objective_results?.filter(q=>attempt.value?.ai_grade?.result.conflict_ids?.includes(q.item_id))??[])
const needsFallback=computed(()=>attempt.value?.exam_id==='caocuan-exam-s1.2'&&!modelSucceeded(attempt.value?.ai_grade))
const canPublish=computed(()=>!objectiveDirty.value&&!!attempt.value&&canPublishReview(attempt.value,scores.value,reviewComment.value,openItems.value)&&JSON.stringify(attempt.value.review_history?.at(-1)?.criteria??null)===JSON.stringify(criteria.value))
const statusNames:Record<string,string>={pending_model:'待模型评分',pending_review:'待批阅',reviewed:'已批阅 · 待发布',published:'已发布',active:'进行中',completed:'已结束',ended:'已结束',clip_complete:'片段完成'}
const roleNames:Record<string,string>={L:'鲁肃',Z:'诸葛亮',C:'曹操',R_LUSU:'鲁肃',R_ZHUGE:'诸葛亮',R_CAO:'曹营统领'}
function labelsFor(q:ExamItem){return criteriaFor(q)}
function date(s:string){return new Date(s).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})}
function message(e:unknown){return e instanceof Error?e.message:'请求未完成，请重试。'}
function chooseAttempt(id:string){selectedAttempt.value=id;objectiveDirty.value=false;const a=detail.value?.attempts.find(x=>x.id===id);fallbackConfirmed.value=a?.status==='reviewed';objectiveResolution.value=Object.fromEntries((a?.ai_grade?.result.conflict_ids??[]).map(qid=>[qid,a?.status==='reviewed'||a?.status==='published'?a.item_scores[qid]??null:null]));reviewComment.value=a?.review_comment??'';scores.value=Object.fromEntries(openItems.value.map(q=>[q.id,typeof a?.item_scores[q.id]==='number'?a.item_scores[q.id]:null]));criteria.value=Object.fromEntries(openItems.value.map(q=>[q.id,a?.review_history?.at(-1)?.criteria?.[q.id]??criteriaFor(q).map(()=>null)]))}
async function loadList(){try{students.value=(await props.request('/api/teacher/students')).students}catch(e){error.value=message(e)}}
async function selectStudent(id:string,keepAttempt=false){const version=++selectionVersion;selectedId.value=id;detailLoading.value=true;error.value='';notice.value='';if(!keepAttempt)detail.value=null
try{const result:Detail=await props.request(`/api/teacher/students/${encodeURIComponent(id)}`);if(version!==selectionVersion)return;detail.value=result;aiState.value=result.ai_assessment??null;comment.value=result.comment?.text??'';const selected=keepAttempt&&result.attempts.some(a=>a.id===selectedAttempt.value)?selectedAttempt.value:result.attempts[0]?.id??'';chooseAttempt(selected)}catch(e){if(version===selectionVersion)error.value=message(e)}finally{if(version===selectionVersion)detailLoading.value=false}}
async function load(){loading.value=true;error.value='';try{const [list,exam]=await Promise.all([props.request('/api/teacher/students'),props.request('/api/teacher/exam')]);students.value=list.students;items.value=exam.items;if(students.value[0])await selectStudent(students.value[0].user_id)}catch(e){error.value=message(e)}finally{loading.value=false}}
async function saveComment(){if(!detail.value||busy.value)return;busy.value=true;error.value='';notice.value='';try{const saved=await props.request(`/api/teacher/students/${encodeURIComponent(selectedId.value)}/comment`,'PUT',{text:comment.value});detail.value.comment=saved;detail.value.comment={...saved,status:'draft'};notice.value='评语草稿已保存。'}catch(e){error.value=message(e)}finally{busy.value=false}}
async function publishComment(){if(!detail.value?.comment||comment.value!==detail.value.comment.text||busy.value)return;busy.value=true;error.value='';try{const saved=await props.request(`/api/teacher/students/${encodeURIComponent(selectedId.value)}/comment/publish`,'POST');detail.value.published_comment=saved;detail.value.comment.status='published';notice.value='此版评语已发布并保留，学生成绩页仍只展示已发布总分。'}catch(e){error.value=message(e)}finally{busy.value=false}}
async function review(){if(!attempt.value||!canReview.value||busy.value)return;busy.value=true;error.value='';try{await props.request(`/api/teacher/attempts/${encodeURIComponent(attempt.value.id)}/review`,'PUT',{scores:scores.value,criteria:criteria.value,comment:reviewComment.value,objective_scores:objectiveResolution.value,confirm_rule_fallback:fallbackConfirmed.value});await selectStudent(selectedId.value,true);notice.value='本卷主观题已批阅。检查总分后，可发布成绩。'}catch(e){error.value=message(e)}finally{busy.value=false}}
async function publish(){if(!attempt.value||!canPublish.value||busy.value)return;busy.value=true;error.value='';try{await props.request(`/api/teacher/attempts/${encodeURIComponent(attempt.value.id)}/publish`,'POST');await selectStudent(selectedId.value,true);await loadList();notice.value='本次成绩已发布，学生现在可以查看总分。'}catch(e){error.value=message(e)}finally{busy.value=false}}
function criterionInput(id:string,index:number,event:Event){const value=(event.target as HTMLInputElement).value;const next=[...(criteria.value[id]??[])];next[index]=value===''?null:Number(value);criteria.value={...criteria.value,[id]:next};scores.value={...scores.value,[id]:next.every(n=>typeof n==='number')?next.reduce<number>((total,n)=>total+Number(n),0):null}}
function answerText(q:ExamItem,a:unknown):string{if(a===undefined||a===null)return'未作答';const label=(id:string)=>q.options?.find(o=>o.id===id)?.text??id;if(Array.isArray(a))return a.map(v=>label(String(v))).join(q.type==='order'?' → ':'；');if(q.parts&&typeof a==='object'){return q.parts.map(part=>`${part.prompt} ${part.options?.find(o=>o.id===(a as Record<string,unknown>)[part.id])?.text??(a as Record<string,unknown>)[part.id]??'未作答'}`).join('\n')}if(typeof a==='object'){return Object.entries(a as Record<string,unknown>).map(([l,r])=>`${q.left?.find(o=>o.id===l)?.text??l} → ${q.right?.find(o=>o.id===r)?.text??r}`).join('\n')}return isWriting(q)||q.type==='fill'?String(a):label(String(a))}
async function runAI(kind:'grade'|'analysis'){
 if(busy.value||!detail.value)return
 const studentId=selectedId.value,attemptId=attempt.value?.id
 if(kind==='grade'&&!attemptId)return
 busy.value=true;error.value='';notice.value=''
 try{
  const path=kind==='grade'?`/api/teacher/attempts/${encodeURIComponent(attemptId!)}/ai-grade`:`/api/teacher/students/${encodeURIComponent(studentId)}/ai-analysis`
  const run:AIRun=await props.request(path,'POST',{request_id:crypto.randomUUID()})
  await selectStudent(studentId,true)
  notice.value=runLabel(run)
 }catch(e){error.value=message(e)}finally{busy.value=false}
}
function applySuggestion(id:string){
 const suggestion=attempt.value?.ai_grade?.result.subjective_suggestions?.find(x=>x.item_id===id)
 const question=openItems.value.find(q=>q.id===id)
 if(!suggestion||!question||busy.value||attempt.value?.status==='published')return
 const values=criteriaFor(question).map(c=>suggestion.criteria.find(x=>x.id===c.id)?.score??null)
 criteria.value={...criteria.value,[id]:values};scores.value={...scores.value,[id]:values.every(n=>typeof n==='number')?values.reduce<number>((a,n)=>a+Number(n),0):null}
 notice.value='已填入本题模型建议；请逐项核读学生原文，再保存批阅。'
}
function objectiveInput(id:string,event:Event){objectiveDirty.value=true;const value=(event.target as HTMLInputElement).value;objectiveResolution.value={...objectiveResolution.value,[id]:value===''?null:Number(value)}}
onMounted(load)
</script>

<template>
<section class="teacher-shell" aria-label="教师学情工作台">
  <header class="teacher-header"><div><span>草船借箭 · 教师工作台</span><h1>查看原话与学习记录</h1></div><button class="teacher-button" @click="emit('close')">返回课件 ↗</button></header>
  <p v-if="error" class="teacher-alert" role="alert">{{error}} <button v-if="!students.length" @click="load">重新加载</button></p><p v-if="notice" class="teacher-notice" role="status">{{notice}}</p>
  <div v-if="loading" class="teacher-empty" role="status">正在读取本班学习记录…</div>
  <div v-else class="teacher-layout">
    <aside class="student-list"><label for="student-search">学生 · {{students.length}}</label><input id="student-search" v-model="search" type="search" placeholder="姓名、学号或班级"><nav aria-label="学生列表"><button v-for="s in filtered" :key="s.user_id" :class="{selected:s.user_id===selectedId}" :disabled="busy" @click="selectStudent(s.user_id)"><span class="student-name">{{s.name}}<small v-if="s.demo">虚构账号</small></span><span class="student-meta">{{s.class_id}} · {{s.user_id}}</span><span class="student-progress">{{s.route_count}} 段路线 · {{s.attempt_count}} 次测试 <b>{{s.published_total===null?'—':`${s.published_total}分`}}</b></span></button></nav><p v-if="!filtered.length" class="teacher-muted">没有符合条件的学生。</p></aside>
    <main class="teacher-detail">
      <div v-if="detailLoading" class="teacher-empty" role="status">正在打开学习记录…</div>
      <template v-else-if="detail">
        <div class="student-heading"><div><span class="teacher-eyebrow">{{detail.student.class_id}} · {{detail.student.user_id}}</span><h2>{{detail.student.name}}<small v-if="detail.student.demo">虚构测试数据</small></h2></div><span class="teacher-mode">{{aiState?.provider.ready?'模型已配置 · 建议需复核':'真实模型尚未配置'}}</span></div>
        <section class="record-section"><div class="section-heading"><h3>学习轨迹</h3><span>{{detail.routes.length}} 条记录</span></div><div v-if="!detail.routes.length" class="teacher-empty inline">尚未开始剧情。完成学习后，路线和作品会出现在这里。</div><ul v-else class="route-lines"><li v-for="r in detail.routes" :key="r.id"><span class="route-dot" aria-hidden="true"></span><strong>{{roleNames[r.role]??r.role}}</strong><span>{{statusNames[r.status]??r.status}}</span><small v-if="r.parent_route_id">新尝试 · 原路 {{r.parent_route_id.slice(-8)}}</small><time>{{date(r.created_at)}}</time></li></ul></section>
        <section class="record-section ai-section" aria-label="AI学习过程分析">
 <div class="section-heading"><h3>AI学习过程分析</h3><span>{{aiState?.provider.model??'DeepSeek'}} · {{aiState?.provider.ready?'可调用':'未配置'}}</span></div>
 <p class="teacher-muted">将本人原话、选择、过程任务及相关帮助交给模型分析。每项判断须指回真实记录，由教师结合课堂情况核读。</p>
 <button class="teacher-button" :disabled="busy" @click="runAI('analysis')">{{busy?'正在处理…':'分析这位学生的决策表现'}}</button>
 <small v-if="aiState?.provider.ready" class="ai-budget">本机剩余调用 {{aiState.provider.calls_remaining}} 次</small>
 <p v-if="aiState?.latest_analysis" class="ai-status">{{runLabel(aiState.latest_analysis)}}</p>
 <template v-if="aiState?.latest_analysis?.mode==='live'&&aiState.latest_analysis.status==='completed'">
  <p>{{aiState.latest_analysis.result.summary}}</p>
  <article v-for="g in aiState.latest_analysis.result.goals??[]" :key="g.goal_id" class="source-record">
   <h4>{{detail.matrix.find(m=>m.goal_id===g.goal_id)?.title??g.goal_id}} · {{g.status==='observed'?'有可分析表现':'记录不足'}}</h4>
   <p>{{g.observation}}</p><p>帮助条件：{{({independent:'未关联帮助',assisted:'有帮助',mixed:'含不同帮助条件',insufficient:'记录不足'} as Record<string,string>)[g.support_condition]??g.support_condition}}</p>
   <p v-if="g.next_step">下一次可尝试：{{g.next_step}}</p>
   <details v-if="g.evidence_ids.length"><summary>查看模型引用的 {{g.evidence_ids.length}} 条记录位置</summary><p v-for="id in g.evidence_ids" :key="id">{{id}} · {{aiState.latest_analysis.result.evidence_map?.[id]?.node_id}} · {{aiState.latest_analysis.result.evidence_map?.[id]?.kind}} · 原记录 {{aiState.latest_analysis.result.evidence_map?.[id]?.source_id}}</p></details>
  </article>
 </template>
 <p v-else class="teacher-muted">{{aiState?.latest_analysis?.error_code?'本次没有形成可用的模型报告，可检查本机服务配置后再试。':'尚无真实模型分析报告。下方原始学习记录仍可供教师查看。'}}</p>
</section>
<section class="record-section"><div class="section-heading"><h3>任务表现观察</h3><span>依据本人作品与实际帮助</span></div><p class="teacher-muted">“已有表现”表示已记录相关作品；不等同于能力已达标。没有个人作品的项目保留未观察。</p>
          <div class="matrix-table"><article v-for="m in detail.matrix" :key="m.goal_id"><div class="matrix-label"><h4>{{m.title}}</h4><span :class="['observation-status',m.status==='observed'?'observed':'']">{{m.status==='observed'?'已有表现 · 待核':'尚未观察'}}</span></div><p>{{m.description}}</p><details v-if="m.evidence.length"><summary>展开 {{m.evidence.length}} 条表现记录</summary><figure v-for="(e,i) in m.evidence" :key="`${e.route_id}-${e.artifact_id??i}`"><blockquote>{{e.text}}</blockquote><figcaption>{{e.kind==='individual_in_group'?'共端中本人署名表达':e.kind==='group'||e.kind==='collaborative'?'共同作品':e.kind==='individual'?'个人作品':e.kind}} · 关联帮助 {{e.support_count}} 次<span v-if="e.node_id"> · 场次 {{e.node_id}}</span><span v-if="e.author_name"> · {{e.author_name}}</span><span v-if="e.artifact_id"> · 作品 {{e.artifact_id.slice(-8)}}</span></figcaption></figure></details></article></div>
        </section>
        <section v-if="detail.s11" class="record-section"><div class="section-heading"><h3>原话、帮助与再试</h3><span>已保存的原始记录</span></div><p v-if="!detail.s11.expressions.length&&!detail.s11.supports.length" class="teacher-muted">尚未留下原话或求助记录。通关和点击不会自动填成个人表现。</p>
          <article v-for="(record,index) in detail.s11.expressions" :key="record.id??index" class="source-record"><h4>{{record.author_name??'未署名'}} <small>{{record.account_id===detail.student.user_id?'本人账号':record.account_id?'已绑定账号':'共端署名，未绑定账号'}}</small></h4><blockquote>{{record.text}}</blockquote><p>场次 {{record.node_id}} · 路线 {{record.route_id.slice(-8)}} · {{record.kind}}<span v-if="record.created_at"> · {{date(record.created_at)}}</span></p><details v-if="record.support_ids?.length"><summary>这句话之前的关联帮助（{{record.support_ids.length}}）</summary><blockquote v-for="help in detail.s11.supports.filter(h=>record.support_ids?.includes(h.id??''))" :key="help.id">{{help.text}}<small> · {{help.source}} · {{help.level}} · {{help.node_id}}</small></blockquote></details><p v-else class="teacher-muted">没有关联帮助记录；不据此判断表达质量。</p></article>
          <details v-if="detail.s11.supports.length"><summary>全部求助记录（{{detail.s11.supports.length}}）</summary><article v-for="(help,index) in detail.s11.supports" :key="help.id??index" class="source-record"><blockquote>{{help.text}}</blockquote><p>{{help.author_name??'未署名'}} · {{help.node_id}} · {{help.level}} · {{help.source}}</p></article></details>
          <details v-if="detail.s11.old_utterances?.length"><summary>再试时保留的旧句（不计新作品）</summary><article v-for="(line,index) in detail.s11.old_utterances" :key="`${line.id}-${index}`" class="source-record"><blockquote>{{line.text}}</blockquote><p>{{line.author_name}} · {{line.node_id}} · 原作者保留</p></article></details>
          <details v-if="detail.s11.events.length"><summary>查看实际动作与当场回应（不作个人能力分）</summary><article v-for="(event,index) in detail.s11.events" :key="index" class="source-record"><p>{{event.author_name??'未署名'}} · {{event.node_id}} · 路线 {{event.route_id.slice(-8)}}</p><strong>{{event.label??event.action??'动作已记录'}}</strong><blockquote>{{event.reaction}}</blockquote></article></details>
        </section>
        <section v-if="detail.s11&&processTasks.length" class="record-section"><div class="section-heading"><h3>船上过程小任务</h3><span>{{processTasks.length}} 项实际记录</span></div><p v-if="!processTasks.length" class="teacher-muted">尚未保存通道、指舷或重听任务记录。</p><article v-for="task in processTasks" :key="`${task.route_id}-${task.record_id}`" class="source-record"><h4>{{taskNames[task.task_id]??task.task_id}} · {{task.author_name}} <small>{{task.account_id===detail.student.user_id?'本人账号':task.account_id?'已绑定账号':'共端署名，未绑定账号'}}</small></h4><p>{{task.node_id}} · 路线 {{task.route_id.slice(-8)}} · {{date(task.created_at)}} · {{task.payload.status==='complete'?'已提交本项':'尚在尝试'}}</p>
          <p v-if="task.task_id==='M03_PASSAGE'">移开挡路物 {{task.payload.placements?.length??0}} 次；通道{{task.payload.blocked_after?'仍有遮挡':'已清空'}}；韩伯通过演示{{task.payload.walked?'已完成':'尚未完成'}}。</p>
          <template v-else-if="task.task_id==='M07_SIDE'"><p v-if="task.payload.first_attempt">首次指向{{sideName(task.payload.first_attempt.side)}}；最终指向{{sideName(task.payload.selected_side)}}。</p><p v-else>尚未指认船舷。</p><ol class="process-attempts"><li v-for="(point,index) in task.payload.attempts??[]" :key="point.sequence">{{index===0?'首次指向':(point.feedback_before?.length??0)+(point.support_ids?.length??0)>0?'提示后指向':'再次指向'}}{{sideName(point.side)}}<small> · 此前界面提示 {{point.feedback_before?.length??0}} 条，关联帮助 {{point.support_ids?.length??0}} 条</small></li></ol><p v-for="hint in task.feedback_display??[]" :key="hint.id">当时呈现的提示：{{hint.text}}</p></template>
          <template v-else-if="task.task_id==='M09_LISTEN'"><p>江面声音查看 {{task.payload.replays?.arrow_change??0}} 次；岸上动静查看 {{task.payload.replays?.shore_report??0}} 次。</p><p v-for="heard in task.payload.heard??[]" :key="heard.sequence">{{heard.clip_id==='arrow_change'?'江面声音':'岸上动静'}} · {{heard.mode==='local_web_audio'?'本地拟音重听':'文字查看'}}</p><blockquote v-if="task.payload.response">{{task.payload.response}}</blockquote><p v-else>尚未留下本人原话。</p></template>
          <ol v-else-if="task.task_id==='M12_TALLY'" class="process-attempts"><li v-for="answer in tallyAttempts(task)" :key="answer.sequence">第{{answer.sequence}}次报数：{{answer.answer_total.toLocaleString()}}支<template v-if="answer.answer_side">；比较{{answer.answer_side==='right'?'右舷较多':answer.answer_side==='left'?'左舷较多':'两舷一样多'}}</template><p>{{answer.feedback?.text}}</p><small>此前反馈 {{answer.feedback_before?.length??0}} 条 · 关联帮助 {{answer.support_ids?.length??0}} 条。保留当时作答，不折算素养分。</small></li></ol>
        </article><p v-if="processTasks.length" class="teacher-muted">这里保留界面操作事实与当时帮助。首指、改正、重听和共同操作均不直接折算成个人能力分。</p></section>
        <section class="record-section"><div class="section-heading"><h3>课题测试与批阅</h3><span>满分 100</span></div><div v-if="!detail.attempts.length" class="teacher-empty inline">尚未提交课题测试。</div><template v-else><label class="attempt-picker">选择答卷<select :value="selectedAttempt" :disabled="busy" @change="chooseAttempt(($event.target as HTMLSelectElement).value)"><option v-for="a in detail.attempts" :key="a.id" :value="a.id">{{date(a.created_at)}} · {{statusNames[a.status]??a.status}}</option></select></label>
          <div v-if="attempt" class="attempt-content"><div class="attempt-overview"><strong>{{attempt.total===null?'待完成批阅':`${attempt.total} / 100`}}</strong><span>{{statusNames[attempt.status]??attempt.status}}</span></div>
            <section class="ai-grade" aria-label="AI试卷评分">
 <div class="section-heading"><h3>模型逐题评分</h3><span>{{runLabel(attempt.ai_grade)}}</span></div>
 <p class="teacher-muted">模型按本卷答案与量规判分。客观题与标准判分不一致的项目单独列出；主观题建议须核读后保存。</p>
 <button v-if="!['reviewed','published'].includes(attempt.status)" class="teacher-button" :disabled="busy" @click="runAI('grade')">{{busy?'正在处理…':'请求模型评分本卷'}}</button>
 <details v-if="attempt.ai_grade?.result.objective_results?.length" class="ai-score-list"><summary>模型客观题评分明细</summary><p v-for="r in attempt.ai_grade.result.objective_results" :key="r.item_id">第{{activeItems.findIndex(q=>q.id===r.item_id)+1}}题：模型 {{r.model_score}} / {{r.max_points}} · 标准判分 {{r.rule_score}} · {{r.status==='agreement'?'一致':'有分歧'}}<br>{{r.reason}}</p></details>
 <div v-for="r in conflicts" :key="r.item_id" class="ai-conflict"><p>第{{activeItems.findIndex(q=>q.id===r.item_id)+1}}题：模型 {{r.model_score}} 分，标准判分 {{r.rule_score}} 分。</p><label>教师复核分数<input type="number" min="0" :max="r.max_points" step="1" :aria-label="`第${activeItems.findIndex(q=>q.id===r.item_id)+1}题客观分歧复核`" :value="objectiveResolution[r.item_id]??''" :disabled="busy||attempt.status==='published'" @input="objectiveInput(r.item_id,$event)"> / {{r.max_points}}</label></div>
 <label v-if="needsFallback&&attempt.status!=='published'" class="ai-fallback"><input v-model="fallbackConfirmed" type="checkbox" :disabled="busy">本次尚无通过校验的模型评分；我已核读客观题标准判分，确认由教师完成本次批阅。</label>
</section>
<details class="objective-answers"><summary>查看客观题作答与得分（{{objectiveMax}}分）</summary><div v-for="q in objectiveItems" :key="q.id"><h4>{{q.prompt}} <span>{{attempt.item_scores[q.id]??'—'}} / {{q.points}}</span></h4><p>学生作答：{{answerText(q,attempt.answers[q.id])}}</p><p v-if="q.answer_key!==undefined">评分依据：{{answerText(q,q.answer_key)}}</p></div></details>
            <article v-for="q in openItems" :key="q.id" class="review-question"><h4>{{q.prompt}}</h4><blockquote>{{answerText(q,attempt.answers[q.id])}}</blockquote><p v-if="q.rubric" class="teacher-muted">{{typeof q.rubric==='string'?q.rubric:Array.isArray(q.rubric)?q.rubric.join('；'):JSON.stringify(q.rubric)}}</p><div v-if="attempt.ai_grade?.result.subjective_suggestions?.some(s=>s.item_id===q.id)" class="ai-suggestion"><template v-for="s in attempt.ai_grade.result.subjective_suggestions.filter(s=>s.item_id===q.id)" :key="s.item_id"><p><strong>模型建议 {{s.suggested_score}} / {{q.points}}</strong> · {{s.feedback}}</p><p v-for="c in s.criteria" :key="c.id">{{labelsFor(q).find(v=>v.id===c.id)?.title??c.id}}：{{c.score}} · {{c.reason}}</p><button v-if="attempt.status!=='published'" class="teacher-button" :disabled="busy" @click="applySuggestion(q.id)">填入本题建议，继续核读</button></template></div><label v-for="(criterion,index) in labelsFor(q)" :key="criterion.id">{{criterion.title}}<input type="number" min="0" :max="criterion.max_points" step="1" :aria-label="`第${activeItems.indexOf(q)+1}题 ${criterion.title}`" :value="criteria[q.id]?.[index]??''" :disabled="attempt.status==='published'||busy" @input="criterionInput(q.id,index,$event)"><span>/ {{criterion.max_points}}</span></label><p class="teacher-muted">本题合计 {{scores[q.id]??'尚未评分'}} / {{q.points}}</p></article>
            <template v-if="attempt.status!=='published'"><label class="review-note">批阅说明（必填）<textarea v-model="reviewComment" maxlength="2000" rows="3" :disabled="busy" placeholder="指出具体表达与改进方向，可保留合理的不同演法。"></textarea></label><div class="review-actions"><button class="teacher-primary" :disabled="busy||!canReview" @click="review">{{busy?'正在保存…':'保存批阅'}}</button><button class="teacher-button" :disabled="busy||!canPublish" @click="publish">发布本次成绩</button><small>{{attempt.status==='reviewed'&&!canPublish?'有尚未保存的批阅修改，请先保存。':'发布后学生只能看到本次总分；已发布答卷不再修改。'}}</small></div></template><p v-else class="teacher-muted">已于 {{attempt.published_at?date(attempt.published_at):'—'}} 发布。此答卷已锁定。<span v-if="attempt.review_comment">批阅说明：{{attempt.review_comment}}</span></p>
            <details v-if="attempt.review_history?.length"><summary>批阅版本（{{attempt.review_history.length}}）</summary><p v-for="revision in attempt.review_history" :key="revision.id">{{date(revision.created_at)}} · {{revision.teacher_id}} · <span v-for="q in openItems" :key="q.id"> · 第{{activeItems.indexOf(q)+1}}题 {{revision.scores[q.id]}} / {{q.points}}</span><br>{{revision.comment}}</p></details>
          </div>
        </template></section>
        <section class="record-section"><div class="section-heading"><h3>综合评语</h3><span v-if="detail.comment">第 {{detail.comment.version}} 版 · {{date(detail.comment.updated_at)}}</span></div><label class="sr-only" for="teacher-comment">给这位学生的综合评语</label><textarea id="teacher-comment" v-model="comment" maxlength="2000" rows="5" class="overall-comment" :disabled="busy" placeholder="从一段具体表现出发，写下值得保留的处理，以及下一次可以尝试的改变。"></textarea><div class="comment-actions"><button class="teacher-primary" :disabled="busy||!comment.trim()" @click="saveComment">保存评语草稿</button><button class="teacher-button" :disabled="busy||!detail.comment||comment!==detail.comment.text||detail.comment.status==='published'" @click="publishComment">发布此版评语</button><small>{{detail.comment?.status==='published'?'此版已发布并保留':'草稿只供教师查看'}}；学生成绩页只显示已发布总分。</small></div><details v-if="detail.published_comment"><summary>已发布评语 · 第 {{detail.published_comment.version}} 版</summary><p class="teacher-muted">{{detail.published_comment.text}}</p></details></section>
        <details v-if="detail.limitations.length" class="teacher-limitations"><summary>本次记录的适用范围</summary><ul><li v-for="l in detail.limitations" :key="l">{{l}}</li></ul></details>
      </template>
      <div v-else-if="!students.length" class="teacher-empty">本账号当前没有可查看的班级学生。请检查本机账号与班级设置。</div>
    </main>
  </div>
</section>
</template>

